#!/usr/bin/env python3
"""Render the rule catalog's generated files (ADR-031 Decision 8, #492).

``src/catalog/engines/*.toml`` and ``src/catalog/patterns/*.toml`` are the single source
of the engine and pattern facts every consumer must agree on. Python reads them through
``src.shared.catalog``. This script writes the two files that cannot:

- ``src/ui/src/utils/engineCatalog.generated.js``: the engine facts the UI uses
  (``engineNames.js``, ``cacheLayer.js``, ``ChartSankey-01.js`` and ``AssignmentGate.js``
  import it), since the UI cannot read TOML at run time;
- ``docs/architecture/rule-catalog.md``: the pattern x engine matrix (support, score,
  penalty, why) next to the engine properties, for review.

Usage:
    uv run python scripts/render_catalog.py            # write both files
    uv run python scripts/render_catalog.py --check    # exit 1 if either is out of date
"""

from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path

REPO_ROOT = Path(__file__).resolve().parent.parent
if str(REPO_ROOT) not in sys.path:
    sys.path.insert(0, str(REPO_ROOT))

from src.report.escaping import md_cell, md_text  # noqa: E402
from src.shared.catalog import ACTIVE, CatalogError, EngineEntry, engine_ids, engines  # noqa: E402
from src.shared.catalog.patterns import EngineSupport, PatternEntry, patterns  # noqa: E402

JS_OUT = REPO_ROOT / "src" / "ui" / "src" / "utils" / "engineCatalog.generated.js"
MD_OUT = REPO_ROOT / "docs" / "architecture" / "rule-catalog.md"

BANNER = (
    "// GENERATED by scripts/render_catalog.py from src/catalog/engines/*.toml -- do not edit.\n"
    "// Change the engine's TOML file, then run: uv run python scripts/render_catalog.py\n"
)


def _js_string(value: str) -> str:
    # Single-quoted, the repo's JS style; json.dumps does the escaping.
    return "'" + json.dumps(value)[1:-1].replace("'", "\\'") + "'"


def _object(name: str, doc: str, rows: list[tuple[str, str]]) -> str:
    body = "".join(f"  {key}: {_js_string(value)},\n" for key, value in rows)
    return f"// {doc}\nexport const {name} = {{\n{body}}};\n"


def render_js(entries: tuple[EngineEntry, ...]) -> str:
    """The generated module's full text for ``entries`` (in catalog display order)."""
    cache_ids = sorted(engine_ids(status=ACTIVE, role="cache"))
    parts = [
        BANNER,
        _object(
            "ENGINE_LABELS",
            "Display name per engine id (display_name).",
            [(e.id, e.display_name) for e in entries],
        ),
        _object(
            "ENGINE_HEX",
            "Live UI colour per engine id (colors.ui).",
            [(e.id, e.colors.ui) for e in entries],
        ),
        _object(
            "ENGINE_BADGE_COLORS",
            "Live UI badge colour per engine id (colors.ui_badge).",
            [(e.id, e.colors.ui_badge) for e in entries],
        ),
        "// Every engine id in the assignment gate's picker order (ui_picker_order).\n"
        "export const ENGINE_PICKER_ORDER = ["
        + ", ".join(_js_string(e.id) for e in sorted(entries, key=lambda e: e.ui_picker_order))
        + "];\n",
        '// Active engines whose role is a cache layer (role = "cache").\n'
        f"export const CACHE_ENGINE_IDS = [{', '.join(_js_string(i) for i in cache_ids)}];\n",
    ]
    return "\n".join(parts)


def _cell(support: EngineSupport | None) -> str:
    """The matrix cell for one engine's entry: what it does to a query's score."""
    if support is None:
        return "missing"
    if support.kind == "fit":
        return (
            f"fit {support.score}" if support.score is not None else f"fit ({support.confidence})"
        )
    if support.kind == "anti_pattern":
        return f"anti {support.severity:g}" + ("" if support.supported else ", no")
    if support.kind == "redesign":
        return f"redesign -{support.penalty}"
    if support.kind == "future":
        return "future"
    if support.kind == "penalized":
        return "**no**"
    if not support.supported:
        return "no"
    return {"native": "native", "unscored": "-"}[support.kind]


def _engine_columns(entries: tuple[EngineEntry, ...]) -> list[EngineEntry]:
    """The engines a pattern file has an entry for: every engine routing can target, then
    the future-enhancement placeholders."""
    decided = engine_ids(status=(*ACTIVE, "future"))
    return [e for e in entries if e.id in decided]


def render_md(entries: tuple[EngineEntry, ...], pattern_entries: tuple[PatternEntry, ...]) -> str:
    """The rule-catalog Markdown page for ``entries`` and ``pattern_entries``."""
    columns = _engine_columns(entries)
    out = [
        "# Rule catalog: patterns x engines",
        "",
        "<!-- GENERATED by scripts/render_catalog.py from src/catalog/ -- do not edit. -->",
        "",
        "Generated from `src/catalog/engines/*.toml` and `src/catalog/patterns/*.toml` "
        "(ADR-031 Decision 8). Change a TOML file, then run "
        "`uv run python scripts/render_catalog.py`. Field definitions: "
        "`src/shared/catalog/engines.py` and `src/shared/catalog/patterns.py`.",
        "",
        "## Engines",
        "",
        "| Engine | Id | Status | Role | System of record |",
        "|---|---|---|---|---|",
    ]
    for e in entries:
        status = "future enhancement" if e.status == "future" else e.status
        out.append(
            f"| {md_cell(e.display_name)} | `{e.id}` | {status} | {e.role} | "
            f"{'yes' if e.system_of_record else 'no'} |"
        )
    out += [
        "",
        "## Pattern x engine matrix",
        "",
        "Each cell is what a query showing the pattern gets on that engine: `fit N` (the "
        "engine's analysis reports it, catalog score N), `fit (level)` (reported with a "
        "confidence level instead of a score), `anti S` (reported as an anti-pattern, "
        "severity S), `native` (has the capability, never penalised), `redesign -N` "
        "(lacks it, bounded redesign, N-point penalty), **no** (cannot run it: takes the "
        "full penalty when another engine reports it as a fit), `no` (cannot run it, no "
        "score effect; `anti S, no` for a reported anti-pattern), `-` (no effect) or "
        "`future` (a future-enhancement placeholder: not modelled yet, never a routing "
        "candidate). "
        "Penalty is the points lost on an engine that reports it as an anti-pattern, or "
        "on every other engine when one reports it as a fit.",
        "",
        "| Pattern | "
        + " | ".join(
            md_cell(e.display_name + (" (future)" if e.status == "future" else "")) for e in columns
        )
        + " | Penalty | Capability | Triage signal | Detectors |",
        "|---|" + "---|" * len(columns) + "---|---|---|---|",
    ]
    for p in pattern_entries:
        cells = [_cell(p.engines.get(e.id)) for e in columns]
        penalty = str(p.penalty) if p.penalty else "-"
        if p.penalty_aliases:
            penalty += " (also " + ", ".join(f"`{a}`" for a in p.penalty_aliases) + ")"
        out.append(
            f"| [`{p.id}`](#{p.id}) | "
            + " | ".join(cells)
            + f" | {penalty} | {p.capability or '-'} | {p.triage_signal or '-'} | "
            f"{len(p.detectors) or 'none'} |"
        )
    out += ["", "## Patterns", ""]
    for p in pattern_entries:
        out += [f"### {p.id}", ""]
        if p.detectors:
            out.append("Detected by " + ", ".join(f"`{d}`" for d in p.detectors) + ".")
        else:
            out.append("No analysis reports this pattern today.")
        for label, note in (("Exemption note", p.exempt_note), ("Redesign note", p.redesign_note)):
            if note:
                out.append(f"{label}: {md_text(note)}")
        out.append("")
        quiet: list[str] = []
        future: list[str] = []
        for e in columns:
            support = p.engines.get(e.id)
            if support is None:
                out.append(f"- {md_text(e.display_name)}: missing")
                continue
            if support.kind == "unscored":
                quiet.append(e.display_name)
                continue
            if support.kind == "future":
                future.append(e.display_name)
                continue
            ref = f" ({support.catalog_id})" if support.catalog_id else ""
            out.append(
                f"- {md_text(e.display_name)}, {_cell(support).replace('**', '')}{ref}: "
                f"{md_text(support.why)}"
            )
        if quiet:
            out.append(f"- No effect on: {md_text(', '.join(quiet))}.")
        if future:
            out.append(f"- Not modelled yet (future enhancement): {md_text(', '.join(future))}.")
        out.append("")
    return "\n".join(out).rstrip("\n") + "\n"


def _outputs() -> list[tuple[Path, str]]:
    return [
        (JS_OUT, render_js(engines())),
        (MD_OUT, render_md(engines(), patterns())),
    ]


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument("--check", action="store_true", help="exit 1 if a file is stale")
    args = parser.parse_args(argv)
    try:
        outputs = _outputs()
    except CatalogError as exc:
        print(f"invalid catalog: {exc}")
        return 1
    if args.check:
        stale = [
            path.relative_to(REPO_ROOT).as_posix()
            for path, expected in outputs
            if (path.read_text(encoding="utf-8") if path.exists() else "") != expected
        ]
        if stale:
            print(f"{', '.join(stale)} out of date. Run: uv run python scripts/render_catalog.py")
            return 1
        print(json.dumps({"render_catalog": "up to date"}))
        return 0
    for path, expected in outputs:
        path.write_text(expected, encoding="utf-8")
    print(json.dumps({"wrote": [path.relative_to(REPO_ROOT).as_posix() for path, _ in outputs]}))
    return 0


if __name__ == "__main__":
    sys.exit(main())
